#!/bin/bash
# Generated by Copilot
# Script to analyze audio files (MP3 and WAV) and display their properties

# Colors for output
GREEN='\033[0;32m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
NC='\033[0m' # No Color

# Default directory is current directory
DIR="${1:-.}"

# Check if ffprobe is installed
if ! command -v ffprobe &> /dev/null; then
    echo -e "${RED}Error: ffprobe is not installed${NC}"
    echo "Install it with: brew install ffmpeg"
    exit 1
fi

# Check if directory exists
if [ ! -d "$DIR" ]; then
    echo -e "${RED}Error: Directory '$DIR' does not exist${NC}"
    exit 1
fi

echo -e "${BLUE}═══════════════════════════════════════════════════════════════${NC}"
echo -e "${GREEN}Audio File Analysis${NC}"
echo -e "${BLUE}Directory: ${YELLOW}$DIR${NC}"
echo -e "${BLUE}═══════════════════════════════════════════════════════════════${NC}"
echo

# Counter for files
count=0

# Find all MP3 and WAV files
while IFS= read -r -d '' file; do
    count=$((count + 1))
    
    # Get filename
    filename=$(basename "$file")
    
    echo -e "${GREEN}[$count] $filename${NC}"
    
    # Get audio properties using ffprobe (including duration)
    properties=$(ffprobe -v error -select_streams a:0 \
        -show_entries stream=codec_name,sample_rate,channels,bit_rate:format=duration \
        -of default=noprint_wrappers=1 "$file" 2>&1)
    
    # Check if ffprobe succeeded
    if [ $? -eq 0 ]; then
        # Parse properties
        codec=$(echo "$properties" | grep "codec_name=" | cut -d'=' -f2)
        sample_rate=$(echo "$properties" | grep "sample_rate=" | cut -d'=' -f2)
        channels=$(echo "$properties" | grep "channels=" | cut -d'=' -f2)
        bit_rate=$(echo "$properties" | grep "bit_rate=" | cut -d'=' -f2)
        duration_seconds=$(echo "$properties" | grep "duration=" | cut -d'=' -f2)
        
        # Format duration as MM:SS
        if [ -n "$duration_seconds" ] && [ "$duration_seconds" != "N/A" ]; then
            minutes=$(echo "$duration_seconds" | awk '{print int($1/60)}')
            seconds=$(echo "$duration_seconds" | awk '{printf "%.2f", $1%60}')
            duration_display="${minutes}:${seconds}"
        else
            duration_display="N/A"
        fi
        
        # Format bitrate (convert to kbps if available)
        if [ -n "$bit_rate" ] && [ "$bit_rate" != "N/A" ]; then
            bit_rate_kbps=$((bit_rate / 1000))
            bit_rate_display="${bit_rate_kbps}k (${bit_rate} bps)"
        else
            bit_rate_display="N/A"
        fi
        
        # Format channels
        case $channels in
            1) channels_display="1 (mono)" ;;
            2) channels_display="2 (stereo)" ;;
            *) channels_display="$channels" ;;
        esac
        
        # Display properties
        echo "  Codec:       ${codec:-N/A}"
        echo "  Sample Rate: ${sample_rate:-N/A} Hz"
        echo "  Channels:    ${channels_display:-N/A}"
        echo "  Bit Rate:    ${bit_rate_display}"
        echo "  Duration:    ${duration_display}"
    else
        echo -e "  ${RED}Error: Could not read audio properties${NC}"
    fi
    
    echo
    
done < <(find "$DIR" -maxdepth 1 \( -iname "*.mp3" -o -iname "*.wav" \) -type f -print0 | sort -z)

# Summary
if [ $count -eq 0 ]; then
    echo -e "${YELLOW}No MP3 or WAV files found in '$DIR'${NC}"
else
    echo -e "${BLUE}═══════════════════════════════════════════════════════════════${NC}"
    echo -e "${GREEN}Total files analyzed: $count${NC}"
    echo -e "${BLUE}═══════════════════════════════════════════════════════════════${NC}"
fi
